from pathlib import Path
import json
base=Path.home()/".local/share/prediction-project-executor/campaigns/FULL-A2Z-LIVE-20261004-V4"
task="A2Z-V4-ASTRA-PREBUILD-DIRECT-20261007-R4P2"
out={}
for rel in ("models/STATE.json","models/CONTINUATION.json","models/BLOCKER.json"):
    p=base/rel
    if p.is_file():
        try:
            o=json.loads(p.read_text(encoding="utf-8"))
        except Exception as e:
            out[rel]={"parse_error":str(e)}
            continue
        if isinstance(o,dict):
            out[rel]={k:o.get(k) for k in sorted(o.keys()) if k in (
                "state","task_id","attempt","retry_at","checkpoint","next_action",
                "reason","type","message","detail","blocked_until","resume_at","usage_limit",
                "model","provider","status"
            )}
rp=base/"model_results"/(task+".json")
out["model_result_exists"]=rp.is_file()
print("ERROR_CLASS=R4P2_ASTRA_USAGE_LIMIT_DEEPSTATE",flush=True)
print("ERROR="+json.dumps(out,separators=(",",":"),sort_keys=True),flush=True)
raise SystemExit(1)
